    <script>
        let attackScore = 0;
        let firmnessScore = 0;
        let soulfulnessScore = 0;
        let totalScore = 0;

        // Get all score buttons
        const scoreButtons = document.querySelectorAll('.score-btn');
        
        // Track active buttons for each section
        let activeButtons = {
            attack: null,
            firmness: null,
            soulfulness: null
        };

        scoreButtons.forEach((button, index) => {
            button.addEventListener('click', function() {
                const value = parseFloat(this.dataset.value);
                let section = '';
                
                // Determine which section this button belongs to
                if (index < 30) {
                    section = 'attack';
                    // Clear previous selection in attack section
                    if (activeButtons.attack) {
                        activeButtons.attack.classList.remove('bg-blue-500', 'text-white');
                    }
                    activeButtons.attack = this;
                    attackScore = value;
                    document.getElementById('attack-score').textContent = value.toFixed(2);
                } else if (index < 60) {
                    section = 'firmness';
                    // Clear previous selection in firmness section
                    if (activeButtons.firmness) {
                        activeButtons.firmness.classList.remove('bg-blue-500', 'text-white');
                    }
                    activeButtons.firmness = this;
                    firmnessScore = value;
                    document.getElementById('firmness-score').textContent = value.toFixed(2);
                } else {
                    section = 'soulfulness';
                    // Clear previous selection in soulfulness section
                    if (activeButtons.soulfulness) {
                        activeButtons.soulfulness.classList.remove('bg-blue-500', 'text-white');
                    }
                    activeButtons.soulfulness = this;
                    soulfulnessScore = value;
                    document.getElementById('soulfulness-score').textContent = value.toFixed(2);
                }
                
                // Highlight clicked button
                this.classList.add('bg-blue-500', 'text-white');
                
                // Calculate and update total score
                totalScore = attackScore + firmnessScore + soulfulnessScore;
                document.getElementById('total-score').textContent = totalScore.toFixed(2);
            });
        });

        console.log('Pencak Silat Detailed Scoring Matrix loaded');
    </script>
